    const int o = (int)(b / tpo);
    const int tile = (int)(b - (int64_t)o * tpo);
    const int c = (tile << 7) + ((int)threadIdx.x << 2);
    const bool valid = c < inner;
    float4 a0 = make_float4(-CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F);
    float4 a1 = a0;
    float4 a2 = a0;
    float4 a3 = a0;
    if (valid) {
      const float4* p4 = reinterpret_cast<const float4*>(&mX(o, 0, c));
      int r = y;
      for (; r + 24 < R; r += 32) {
        a0 = fmax4(a0, __ldcs(p4 + (int64_t)(r + 0) * rstride4));
        a1 = fmax4(a1, __ldcs(p4 + (int64_t)(r + 8) * rstride4));
        a2 = fmax4(a2, __ldcs(p4 + (int64_t)(r + 16) * rstride4));
        a3 = fmax4(a3, __ldcs(p4 + (int64_t)(r + 24) * rstride4));
      }
      for (; r < R; r += 8) {
        a0 = fmax4(a0, __ldcs(p4 + (int64_t)r * rstride4));
      }
    }
    smax4[y][threadIdx.x] = fmax4(fmax4(a0, a1), fmax4(a2, a3));
    __syncthreads();
    if (y == 0 && valid) {
      float4 m = smax4[0][threadIdx.x];
